import{c as t,Q as r,j as o,m as a}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Graph engineering vs Loop engineering","description":"","frontmatter":{"url":"https://x.com/ericosiu/status/2079991948106957131","title":"Graph engineering vs Loop engineering","author":"ericosiu","archived":"2026-07-26T00:00:00.000Z","handle":"@ericosiu","published":"2026-07-22T00:00:00.000Z","stats":"225 likes · 41 retweets · 357 bookmarks · 22945 views","tags":["graph-engineering","loop-engineering","comparison"],"type":"tweet"},"headers":[],"relativePath":"research/tweets/2026-07-22-@ericosiu-957131.md","filePath":"research/tweets/2026-07-22-@ericosiu-957131.md","lastUpdated":1785909234000}'),s={name:"research/tweets/2026-07-22-@ericosiu-957131.md"};function n(i,e,d,h,p,g){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="graph-engineering-vs-loop-engineering-—-ericosiu" tabindex="-1">Graph engineering vs Loop engineering — @ericosiu <a class="header-anchor" href="#graph-engineering-vs-loop-engineering-—-ericosiu" aria-label="Permalink to &quot;Graph engineering vs Loop engineering — @ericosiu&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/ericosiu/status/2079991948106957131" target="_blank" rel="noreferrer">https://x.com/ericosiu/status/2079991948106957131</a><strong>作者</strong>：ericosiu（@ericosiu） <strong>發布日期</strong>：2026-07-22 <strong>收錄日期</strong>：2026-07-26 <strong>類型</strong>：推文 <strong>統計</strong>：225 likes · 41 retweets · 357 bookmarks · 22945 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Graph engineering vs Loop engineering:</p><p>Graph engineering is deciding where the work is allowed to go. You lay out the steps, the rules, who has to approve what, and the safety checks. It keeps things controlled and predictable.</p><p>Loop engineering is making the work get better each time it runs. The agent does the task, checks its own result, and tries again a little sharper. It keeps things improving.</p><p>Graph is the rails. Loop is the motor.</p><p>Rails keep you from crashing. The motor is what actually moves you forward.</p><p>Build the loop first when you want a task to keep improving on its own.</p><p>Add the graph once the work has handoffs, approvals, or steps you can&#39;t afford to get wrong.</p><p>Strong agents need both.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：用「軌道 vs 引擎」的比喻把 Graph Engineering（控制工作能去哪、誰要核可、安全檢查）與 Loop Engineering（讓同一任務一輪比一輪更好）分開定位，主張兩者互補而非互斥，先建 loop 求進步、有 handoff/核可/高風險步驟時再加 graph 求可控。</p><h3 id="脈絡" tabindex="-1">脈絡 <a class="header-anchor" href="#脈絡" aria-label="Permalink to &quot;脈絡&quot;">​</a></h3><ul><li>這是同批熱潮中少數明確定義兩詞邊界、而非單純宣傳其中一詞的推文，發布時間（7/22）晚於 @steipete 起點貼文（7/18）與兩篇長文（7/20、7/21），屬於熱潮稍降溫後的收斂性總結</li><li>「Graph = 決定工作能去哪（steps/approval/safety checks）」與本 workspace <code>.claude/rules/graph.md</code> 的委派拓撲定位（誰是節點、邊怎麼連、gate 不跨 agent 邊界）方向一致；「Loop = 讓工作一輪比一輪更好」與 <code>.claude/rules/loop.md</code> 的迭代驗證引擎定位也一致——<strong>兩份 workspace 規則檔恰好對應本推文的二分，且都已存在，並非因本推文才新增</strong>，故本則屬於外部獨立收斂驗證而非新增知識</li><li>推文全文未附任何具體數字或案例，是純概念性比喻，不含需要查證的量化宣稱</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>7/10</td><td>二分定義與既有 <code>graph.md</code>/<code>loop.md</code> 分工高度吻合，可作為對外解釋兩份規則檔分工的簡短佐證引用</td></tr><tr><td>B. 創新性 (20%)</td><td>5/10</td><td>比喻清晰但屬整理既有概念，非新機制</td></tr><tr><td>C. 證據品質 (20%)</td><td>4/10</td><td>純概念闡述，無數據或案例佐證</td></tr><tr><td>D. 技術深度 (15%)</td><td>3/10</td><td>停留在比喻層次，未給出具體實作細節</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>「軌道 vs 引擎」二分適用任何 agent 系統設計討論</td></tr><tr><td><strong>加權總分</strong></td><td><strong>5.55/10</strong></td><td>7×0.3+5×0.2+4×0.2+3×0.15+8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip（外部驗證引用） <strong>理由</strong>：概念與 <code>.claude/rules/graph.md</code>／<code>.claude/rules/loop.md</code> 既有分工重合，可作簡短佐證但不產生新規則內容。</p>',21)])])}const u=t(s,[["render",n]]);export{c as __pageData,u as default};
